#include "histogram.h"
#include <stdlib.h>
*/
import "C"
import (
  "errors"
  "unsafe"
)

func ComputeHistogram(data []int) (string, error) {
  if len(data) == 0 {
    return "", errors.New("empty data")
  }
  // allocate C array
  cdata :=(*C.int)(unsafe.Pointer(&data[0]))
